// NIV note: English-only product; pt-BR locale removed (see ADR-018-english-only-product).
// Mock-only helper — an "active" node (complete Dual Authorization) in the English locale,
// with simulated cached audio. Represents content predating Amendment 4, migrated.
function contentActive(en: string): SpeechTreeNode['content'] {
  return {
    en: { text: en, audioRef: `audio/en/${en.toLowerCase().replace(/[^a-z0-9]+/g, '-')}.mp3`, caregiverConfirmed: true, patientConfirmed: true },
  };
}

